<script lang="ts">
 import {goto} from '$app/navigation';import type {Claim,User} from '../types';import {total,money} from '../money';import Status from './Status.svelte';import Icon from './Icon.svelte';
 export let claims:Claim[]=[];export let users:User[]=[];export let team=false;
</script>
{#if claims.length}<div class="table-scroll"><table class="claims-table"><thead><tr><th>Claim / purpose</th>{#if team}<th>Employee</th>{/if}<th>Submitted</th><th>Status</th><th class="num">Amount</th><th><span class="sr-only">Open</span></th></tr></thead><tbody>{#each claims as c}<tr><td><a class="claim-link" href={'/claims/'+c.id}>{c.title||'Untitled draft'}</a><small>{c.number} <span class="separator">·</span> {c.costCentre||'Cost centre not set'}</small></td>{#if team}<td>{users.find(u=>u.id===c.ownerId)?.name}<small>{c.department}</small></td>{/if}<td class="date-cell">{(c.submittedAt||c.createdAt).slice(0,10)}{#if c.status==='Submitted'&&Date.now()-Date.parse(c.submittedAt!)>3*86400000}<small class="text-warning">Over 3 days</small>{/if}</td><td><Status status={c.status}/></td><td class="num"><strong>{money(total(c.lines))}</strong><small>{c.lines.length} expense{c.lines.length===1?'':'s'}</small></td><td><button class="icon-button" aria-label={'Open '+c.number} onclick={()=>goto('/claims/'+c.id)}><Icon name="chevron" size={17}/></button></td></tr>{/each}</tbody></table></div>{:else}<div class="empty-state"><Icon name="folder" size={36}/><h3>No claims to show</h3><p>Try a different filter, or create your first expense claim.</p></div>{/if}